using UnityEngine;

public class FlappyBirdController : MonoBehaviour
{
    public float jumpForce = 5f;
    public float gravity = 9.8f;
    public float pipeSpeed = 2f;
    public float pipeSpawnInterval = 2f;

    private Rigidbody2D rb;
    private float nextPipeSpawnTime;

    void Start()
    {
        rb = GetComponent<Rigidbody2D>();
        nextPipeSpawnTime = Time.time + pipeSpawnInterval;
    }

    void Update()
    {
        // Player input
        if (Input.GetButtonDown("Jump"))
        {
            rb.velocity = Vector2.up * jumpForce;
        }

        // Spawn new pipes
        if (Time.time >= nextPipeSpawnTime)
        {
            SpawnPipe();
            nextPipeSpawnTime = Time.time + pipeSpawnInterval;
        }

        // Apply gravity
        rb.velocity -= Vector2.up * gravity * Time.deltaTime;
    }

    void SpawnPipe()
    {
        // Create a new pipe game object
        GameObject pipe = new GameObject("Pipe");
        pipe.AddComponent<BoxCollider2D>();
        pipe.AddComponent<Rigidbody2D>();
        pipe.GetComponent<Rigidbody2D>().gravityScale = 0f;

        // Set the pipe's position and size
        float pipeHeight = Random.Range(-2f, 2f);
        pipe.transform.position = new Vector3(10f, pipeHeight, 0f);
        pipe.transform.localScale = new Vector3(1f, 4f, 1f);

        // Add a script to move the pipe
        PipeMovement pipeScript = pipe.AddComponent<PipeMovement>();
        pipeScript.speed = pipeSpeed;
    }
}

public class PipeMovement : MonoBehaviour
{
    public float speed = 2f;

    void Update()
    {
        // Move the pipe to the left
        transform.Translate(Vector3.left * speed * Time.deltaTime);

        // Destroy the pipe when it goes off-screen
        if (transform.position.x < -10f)
        {
            Destroy(gameObject);
        }
    }
}
```

