```sas
/* Step 1: Import the dataset */
data mydata;
    infile datalines delimiter=',' dsd;
    input Outcome $ Var1 Var2 Var3 Var4 Var5;
    datalines;
    1,2.3,3.1,4.2,5.1,6.3
    0,1.5,2.4,3.5,4.1,5.9
    1,3.6,5.7,2.9,1.3,0.5
    0,2.4,3.2,4.3,5.9,6.8
    1,4.1,2.3,3.4,2.3,1.2
    0,1.2,4.5,3.1,2.8,3.3
    ; /* Sample data created for demonstration */

/* Step 2: Convert Outcome variable to a binary numeric format */
data mydata;
    set mydata;
    if Outcome = '1' then Outcome_num = 1;
    else Outcome_num = 0;
run;

/* Step 3: Prepare data for logistic regression with LASSO */
proc hpgenselect data=mydata;
    /* Step 4: Specify the model */
    model Outcome_num(event='1') = Var1 Var2 Var3 Var4 Var5 / selection=lasso;

    /* Step 5: Specify options for LASSO */
    /* The LASSO selection method will shrink coefficients of less important variables to zero */
    selection=lasso(choose=validate stop=none) /* Choose validation method for model selection */
    selection=lasso(choose=CV) /* Cross-validation method to choose the best lambda */
    lambda=0.1 /* Initial value of lambda for LASSO */
    details /* Provides detailed output of the selection process */;

    /* Step 6: Output the selected variables and their estimates */
    output out=SelectedVars predicted=PredictedValues;

    /* Step 7: Specify the output dataset for the parameter estimates */
    ods output ParameterEstimates=ParamEst;

run;

/* Step 8: View the results of the model */
proc print data=SelectedVars; 
    title "Predicted Values and Selected Variables"; 
run;

proc print data=ParamEst; 
    title "Parameter Estimates for Selected Variables"; 
run;

/* Step 9: Evaluate model performance using ROC curve */
proc logistic data=mydata plots(overlay)=roc; 
    model Outcome_num(event='1') = Var1 Var2 Var3 Var4 Var5; 
run;
```

