// pages/api/search.js  
import {  
  scrapeYunnan, scrapeKunming, scrapePanlong,  
  scrapeWuhua, scrapeGuandu  
} from '../../lib/scrapers';  

export default async function handler(req, res) {  
  const { q } = req.query;  
  if (!q) return res.status(400).json({ error: '缺少查询参数 q' });  

  // 并发抓取  
  const tasks = [  
    scrapeYunnan(q), scrapeKunming(q), scrapePanlong(q),  
    scrapeWuhua(q), scrapeGuandu(q)  
  ];  

  const settled = await Promise.allSettled(tasks);  
  const results = settled.map((st, i) => {  
    if (st.status === 'fulfilled') return st.value;  
    // 出现单馆抓取异常也不影响整体返回  
    const name = ['云南省图书馆','昆明市图书馆','盘龙区图书馆','五华区图书馆','官渡区图书馆'][i];  
    return { name, error: st.reason.message };  
  });  

  res.status(200).json({ data: results });  
}  

