public class BubbleSort {
    // 方法：冒泡排序
    public static void bubbleSort(int[] arr) {
        int n = arr.length;
        boolean swapped;
        // 遍历所有数组元素
        for (int i = 0; i < n - 1; i++) {
            swapped = false;
            // 每次遍历将最大值“冒泡”到末尾
            for (int j = 0; j < n - 1 - i; j++) {
                if (arr[j] > arr[j + 1]) {
                    // 交换相邻元素
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                    swapped = true;
                }
            }
            // 如果没有进行任何交换，说明数组已经有序，可以提前结束
            if (!swapped) {
                break;
            }
        }
    }

