def is_palindrome(word):
    """
    Check if a word is a palindrome (reads the same forwards and backwards)
    """
    # Convert to lowercase and remove spaces/punctuation for better checking
    cleaned_word = ''.join(char.lower() for char in word if char.isalnum())

    # Compare the word with its reverse
    return cleaned_word == cleaned_word[::-1]

def main():
    while True:
        user_input = input("Enter a word to check if it's a palindrome (or 'quit' to exit): ")

        if user_input.lower() == 'quit':
            break

        if is_palindrome(user_input):
            print(f"'{user_input}' is a palindrome! ✓")
        else:
            print(f"'{user_input}' is not a palindrome. ✗")
        print()

if __name__ == "__main__":
    main()
```

