def is_palindrome_iterative(word):
    """
    Check palindrome by comparing characters from both ends
    """
    # Clean the input
    cleaned = ''.join(char.lower() for char in word if char.isalnum())

    left = 0
    right = len(cleaned) - 1

    while left < right:
        if cleaned[left] != cleaned[right]:
            return False
        left += 1
        right -= 1

    return True

